package ai.eva.android.probe;
import android.os.*;import org.json.*;
final class PhoneSelfCheck {
 static String find(JSONObject snapshot,String key,String value)throws Exception{JSONArray rows=snapshot.getJSONArray("nodes");for(int i=0;i<rows.length();i++)if(rows.getJSONObject(i).optString(key).equalsIgnoreCase(value))return rows.getJSONObject(i).getString("id");throw new Exception("node missing: "+value);}
 static JSONObject awaitText(android.content.Context c,String text)throws Exception{for(int n=0;n<20;n++){Thread.sleep(150);JSONObject screen=run(c,"observe");if(!screen.optString("package").equals(c.getPackageName()))throw new Exception("测试被切换 App 中断，请留在测试页重试");try{find(screen,"text",text);return screen;}catch(Exception ignored){}}throw new Exception("操作后 3 秒仍未观察到测试文字："+text);}
 static JSONObject run(android.content.Context context,String action)throws Exception{return PhoneTools.execute(context,new JSONObject().put("action",action));}
 static String check(android.content.Context context){try{PhoneAccessibility.armed=true;PhoneAccessibility.generation++;JSONObject screen=run(context,"observe");if(!screen.getString("package").equals(context.getPackageName()))throw new Exception("fixture not foreground");String input=find(screen,"description","fixture-input");JSONObject applied=PhoneTools.execute(context,new JSONObject().put("action","input").put("snapshot",screen.getString("snapshot")).put("node",input).put("text","phone-use-check"));if(!applied.optBoolean("dispatched"))throw new Exception("系统拒绝输入操作");screen=awaitText(context,"phone-use-check");String button=find(screen,"text","fixture-click");PhoneTools.execute(context,new JSONObject().put("action","click").put("snapshot",screen.getString("snapshot")).put("node",button));screen=awaitText(context,"fixture-clicked");String child=find(screen,"text","fixture-child");PhoneTools.execute(context,new JSONObject().put("action","click").put("snapshot",screen.getString("snapshot")).put("node",child));screen=awaitText(context,"ancestor-clicked");if(!run(context,"screenshot").getString("imageUrl").startsWith("data:image/jpeg;base64,"))throw new Exception("screenshot missing");PhoneAccessibility.stopControl();try{run(context,"observe");throw new Exception("stopped control still readable");}catch(java.io.IOException expected){}PhoneShellService shell=new PhoneShellService();Parcel in=Parcel.obtain(),out=Parcel.obtain();try{in.writeInterfaceToken(PhoneShellService.TOKEN);in.writeString("printf eva-shell-fixture");shell.transact(1,in,out,0);out.readException();JSONObject result=new JSONObject(out.readString());if(!result.optString("output").equals("eva-shell-fixture")||result.optInt("exitCode",-1)!=0)throw new Exception("shell stream failed: "+result);if(result.getInt("uid")!=android.os.Process.myUid())throw new Exception("unexpected identity");}finally{in.recycle();out.recycle();}return "PASS: 真机控件读取、输入、点击、父控件点击、截图、停止后拒绝访问；Shell 流测试仅使用应用 UID，未验证 Shizuku 授权。";}catch(Exception e){return "FAIL: "+e.toString();}finally{PhoneAccessibility.stopControl();if(PhoneTaskService.keep(context))PhoneTaskService.restore(context);else context.stopService(new android.content.Intent(context,PhoneTaskService.class));}}
}
